def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]
    opp_def = sum(1 for a in opp if a == 'D')

    # Short burn-in: cooperate and reciprocate immediate defection only.
    if n < 6:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        return 'C'

    # Endgame: slight exploitation opportunity, but only if partner is safe.
    if n >= 96:
        if opp_def == 0:
            return 'D' if n >= 98 else 'C'
        if opp_def * 4 < n:
            return 'D' if n >= 95 else 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Recent window statistics.
    w = 12 if n >= 12 else n
    rec_opp = opp[-w:]
    rec_me = me[-w:]
    rec_def = sum(1 for a in rec_opp if a == 'D')
    rec_my_def = sum(1 for a in rec_me if a == 'D')

    # Count trailing opponent defection streak.
    streak_d = 0
    for a in reversed(opp):
        if a == 'D':
            streak_d += 1
        else:
            break

    # Count trailing opponent cooperation streak.
    streak_c = 0
    for a in reversed(opp):
        if a == 'C':
            streak_c += 1
        else:
            break

    # Near-always-defector: minimize losses, rare probe.
    if opp_def * 5 >= n * 4 and n >= 10:
        if last_opp == 'C' and streak_c >= 2:
            return 'C'
        return 'D'

    # Very cooperative partner: keep mutual cooperation; avoid needless exploitation.
    if opp_def <= max(1, n // 20):
        if last_opp == 'D':
            # forgive isolated disruption
            if streak_d == 1 and rng.random() < 0.85:
                return 'C'
            return 'D'
        # mostly cooperate; rare probing only very late
        if n >= 90 and opp_def == 0 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Mostly cooperative, occasional defections: generous tit-for-tat with repair.
    if rec_def <= 2 and opp_def * 4 < n:
        if last_opp == 'D':
            # one-round punishment then attempt repair
            if streak_d >= 2:
                if streak_c == 0 and rng.random() < 0.5:
                    return 'C'
                return 'D'
            return 'D'
        # partner cooperated: recover cooperation
        if streak_c >= 2 or last_me == 'D':
            return 'C'
        if rec_my_def > 0:
            return 'C'
        return 'C'

    # Moderate defection rate: measured reciprocity.
    if rec_def * 10 <= w * 5:
        if last_opp == 'D':
            if streak_d == 1:
                # retaliate once, then try to restore
                return 'D'
            if streak_d == 2:
                if rng.random() < 0.3:
                    return 'C'
                return 'D'
            if streak_d >= 3:
                if rng.random() < 0.15:
                    return 'C'
                return 'D'
        else:
            # If we've been defecting too long, restore cooperation
            if rec_my_def >= 3 and streak_c >= 1:
                return 'C'
            return 'C'

    # High defection rate: punish, but keep small chance of repair.
    if last_opp == 'D':
        if streak_d >= 2:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        return 'D'
    # Partner cooperated.
    if streak_c >= 3 or rec_def <= 1:
        return 'C'
    if rng.random() < 0.25:
        return 'C'
    return 'D'
